// Port of mozc/src/dictionary/user_pos.{h,cc} (3.35.6354).

import GenmaiBase
import GenmaiProtocol

/// `mozc::dictionary::UserPos`.
///
/// This implementation of UserPos uses a sorted array of tokens to
/// efficiently lookup required data.  There are two required data, string array
/// and token array, which are generated by ./gen_user_pos_data.py
/// (`DataManager.getUserPosData()`).
///
/// * Binary format
///
/// ** String array
/// All the strings, such as key and value suffixes, are serialized into one
/// array using SerializedStringArray in such a way that array is sorted in
/// ascending order.  In the token array (see below), every string is stored as
/// an index to this array.
///
/// ** Token array
///
/// The token array is an array of 8 byte blocks each of which has the following
/// layout:
///
///     | POS index  (2 bytes)          |
///     | Value suffix index (2 bytes)  |
///     | Key suffix index  (2 bytes)   |
///     | Conjugation ID (2 bytes)      |
///
/// The array is sorted in ascending order of POS index so that we can use binary
/// search to lookup necessary information efficiently.  Note that there are
/// tokens having the same POS index.
///
/// `open` (C++ virtual methods) for testing/mocking. `@unchecked Sendable`: the
/// state is immutable after initialization (subclasses must keep it so).
open class UserPos: @unchecked Sendable {
  public typealias PosType = Genmai_UserDictionary_UserDictionary.PosType

  /// `UserPos::Token`.
  public struct Token: Sendable, Equatable {
    public var key: String = ""
    public var value: String = ""
    /// internal POS id used for lid/rid.
    public var id: UInt16 = 0
    /// POS information. UserDictionary::PosType.
    public var rawPosType: UInt8 = 0
    // The actual cost of user dictionary entries are populated
    // in the dictionary lookup time.

    public init() {}

    public init(key: String, value: String, id: UInt16, posType: PosType) {
      self.key = key
      self.value = value
      self.id = id
      self.rawPosType = UInt8(posType.rawValue)
    }

    /// Returns nil if `rawPosType` is not a valid PosType.
    public var posType: PosType? { PosType(rawValue: Int(rawPosType)) }

    public mutating func setPosType(_ posType: PosType) {
      rawPosType = UInt8(posType.rawValue)
    }
  }

  private struct TokenArrayData {
    var posIndex: UInt16
    var valueSuffixIndex: UInt16
    var keySuffixIndex: UInt16
    var conjugationId: UInt16
  }

  private let tokenArrayData: DataView
  // tokenArrayIndex[posType] = {index to tokenArrayData};
  private var tokenArrayIndex: [[Int]] = []
  private var stringArray = SerializedStringArray()
  private var posList: [String] = []

  /// Initializes the user pos from the given binary data.
  public init(_ tokenArrayData: DataView, _ stringArrayData: DataView) {
    assert(tokenArrayData.count % 8 == 0)
    self.tokenArrayData = tokenArrayData
    stringArray.set(stringArrayData.bytes, owner: stringArrayData.owner)
    initPosList()
  }

  /// For testing.
  public init() {
    tokenArrayData = DataView()
  }

  @inline(__always)
  private func getTokenArrayData(_ i: Int) -> TokenArrayData {
    let o = i * 8
    return TokenArrayData(
      posIndex: tokenArrayData.load(fromByteOffset: o),
      valueSuffixIndex: tokenArrayData.load(fromByteOffset: o + 2),
      keySuffixIndex: tokenArrayData.load(fromByteOffset: o + 4),
      conjugationId: tokenArrayData.load(fromByteOffset: o + 6))
  }

  private var tokenArrayDataSize: Int { tokenArrayData.count / 8 }

  private func initPosList() {
    // make pos_list_.
    var seen = Set<UInt16>()
    for i in 0..<tokenArrayDataSize {
      let token = getTokenArrayData(i)
      if !seen.insert(token.posIndex).inserted {
        continue
      }
      posList.append(stringArray[Int(token.posIndex)])
    }

    // make token_array_index_
    var posToIndex: [[UInt8]: [Int]] = [:]
    for i in 0..<tokenArrayDataSize {
      let pos = Array(stringArray.bytes(at: Int(getTokenArrayData(i).posIndex)))
      posToIndex[pos, default: []].append(i)
    }

    tokenArrayIndex = Array(repeating: [], count: kPosTypeStringTable.count)
    for i in 0..<kPosTypeStringTable.count {
      let pos = Array(kPosTypeStringTable[i].0.utf8)
      if let index = posToIndex[pos] {
        tokenArrayIndex[i] = index
      } else {
        GenmaiLog.error("\(kPosTypeStringTable[i].0) is not defined in the UserPosData")
      }
    }
  }

  /// Virtual for testing/mocking.
  open func getPosList() -> [String] { posList }

  open func getTokens(_ key: String, _ value: String, _ posType: PosType) -> [Token] {
    if key.isEmpty || value.isEmpty {
      return []
    }
    let tokenArrayIndex = self.tokenArrayIndex[posType.rawValue]
    if tokenArrayIndex.isEmpty {
      return []
    }

    var tokens: [Token] = []
    tokens.reserveCapacity(tokenArrayIndex.count)
    let first = getTokenArrayData(tokenArrayIndex[0])
    if tokenArrayIndex.count == 1 {  // no conjugation
      tokens.append(Token(key: key, value: value, id: first.conjugationId, posType: posType))
    } else {
      // expand all other forms
      var keyStem = key.utf8[...]
      var valueStem = value.utf8[...]
      // assume that conjugation_form[0] contains the suffix of "base form".
      let baseKeySuffix = stringArray.bytes(at: Int(first.keySuffixIndex))
      let baseValueSuffix = stringArray.bytes(at: Int(first.valueSuffixIndex))

      if baseKeySuffix.count < key.utf8.count && baseValueSuffix.count < value.utf8.count
        && key.utf8.reversed().starts(with: baseKeySuffix.reversed())
        && value.utf8.reversed().starts(with: baseValueSuffix.reversed())
      {
        keyStem = keyStem.dropLast(baseKeySuffix.count)
        valueStem = valueStem.dropLast(baseValueSuffix.count)
      }
      for i in 0..<tokenArrayIndex.count {
        let src = getTokenArrayData(tokenArrayIndex[i])
        let keySuffix = stringArray.bytes(at: Int(src.keySuffixIndex))
        let valueSuffix = stringArray.bytes(at: Int(src.valueSuffixIndex))
        tokens.append(
          Token(
            key: String(decoding: Array(keyStem) + Array(keySuffix), as: UTF8.self),
            value: String(decoding: Array(valueStem) + Array(valueSuffix), as: UTF8.self),
            id: src.conjugationId, posType: posType))
      }
    }
    return tokens
  }

  public func getPosIds(_ pos: String) -> UInt16? {
    guard let posType = UserPos.toPosType(pos) else {
      return nil
    }
    let tokenArrayIndex = self.tokenArrayIndex[posType.rawValue]
    if tokenArrayIndex.isEmpty {
      return nil
    }
    return getTokenArrayData(tokenArrayIndex[0]).conjugationId
  }

  /// Returns the string representation of PosType.
  /// For historical reason, the pos was represented in Japanese characters.
  public static func getStringPosType(_ posType: PosType) -> String {
    kPosTypeStringTable[posType.rawValue].0
  }

  /// Returns the cost of PosType.
  /// - ABBREVIATION always returns its base cost (200) without cost_penalty.
  /// - If cost is 0 in user_pos.def (e.g. verbs/adjectives), default cost (5000)
  ///   is returned without applying cost_penalty.
  /// - For other POS types (cost > 0), gradually phases out the per-POS discount
  ///   (2500 - cost) as cost_penalty approaches 2500, and scales as
  ///   2500 + cost_penalty for larger penalties.
  public static func getCostFromPosType(_ posType: PosType, _ costPenalty: Int = 0) -> UInt16 {
    if posType == .abbreviation {
      return kPosTypeStringTable[posType.rawValue].1  // Always 200
    }

    let cost = Int(kPosTypeStringTable[posType.rawValue].1)

    let kDefaultCost: UInt16 = 5000
    if cost == 0 {
      // When cost is 0 in user_pos.def (e.g. verbs/adjectives), a large default
      // cost is used. In this case, no extra entry count penalty needs to be
      // added.
      return kDefaultCost
    }

    // Gradually phase out the per-POS discount (kStandardCost - cost) as
    // cost_penalty approaches kStandardCost (2500), so all POS types smoothly
    // converge to 5000 without a step jump, and continue to scale as
    // 2500 + cost_penalty for large dictionaries.
    let kStandardCost = 2500
    let effectiveBaseCost = cost + (kStandardCost - cost) * min(costPenalty, kStandardCost) / kStandardCost
    // The C++ returns uint16_t (implicit truncation).
    return UInt16(truncatingIfNeeded: effectiveBaseCost + costPenalty)
  }

  private static let kPosTypeMap: [[UInt8]: Int] = {
    var posTypeMap: [[UInt8]: Int] = [:]
    for i in 0..<kPosTypeStringTable.count {
      posTypeMap[Array(kPosTypeStringTable[i].0.utf8)] = i
    }
    return posTypeMap
  }()

  /// Returns the PosType of the string representation, or nil (C++: INVALID)
  /// if the given pos is invalid.
  public static func toPosType(_ stringPosType: String) -> PosType? {
    guard let index = kPosTypeMap[Array(stringPosType.utf8)] else {
      return nil
    }
    return PosType(rawValue: index)
  }
}
